me zone, player1_last_seen_at timestamp with time zone, player2_last_seen_at timestamp with time zone, player1_reconnect_grace_used boolean, player2_reconnect_grace_used boolean, is_active boolean, active_until timestamp with time zone, action_points_enabled boolean, player1_action_points integer, player2_action_points integer, turn_index bigint, action_points_per_turn integer, action_costs jsonb, max_attacks_per_card integer, triple_combo_enabled boolean, generic_combo_enabled boolean, formation_enabled boolean, status_effects_enabled boolean, player1_avatar_url text, player2_avatar_url text);
